const hamburger=document.getElementById("hamburger"),navMenu=document.getElementById("navMenu");hamburger&&navMenu&&hamburger.addEventListener("click",()=>{navMenu.classList.toggle("active")});const ctaShop=document.querySelector(".cta-btn"),productsSection=document.getElementById("products");ctaShop&&productsSection&&ctaShop.addEventListener("click",()=>{productsSection.scrollIntoView({behavior:"smooth"})});const productGrid=document.getElementById("productGrid");async function fetchProducts(){if(productGrid)try{const t=await fetch("https://dummyjson.com/products");displayProducts((await t.json()).products.slice(0,12))}catch(t){productGrid&&(productGrid.innerHTML="<p>Error loading products</p>")}}function displayProducts(t){productGrid.replaceChildren(),t.forEach(t=>{const e=document.createElement("div");e.classList.add("product-card");const c=document.createElement("img");c.src=t.thumbnail||"",c.alt=t.title||"",c.loading="lazy",c.decoding="async",c.sizes="(max-width: 768px) 90vw, (max-width: 992px) 45vw, 22vw",c.width=300,c.height=200;const n=document.createElement("h3");n.textContent=t.title||"";const o=document.createElement("p");o.textContent=`$${t.price}`;const d=document.createElement("button");d.type="button",d.textContent="View",d.addEventListener("click",()=>{window.location.href=`product.html?id=${t.id}`}),e.append(c,n,o,d),productGrid.appendChild(e)})}function viewProduct(t){window.location.href=`product.html?id=${t}`}fetchProducts(),"function"==typeof updateCartCountDisplay&&updateCartCountDisplay();